import{_ as o,c as r,o as n,ah as s}from"./chunks/framework.RCw5T9E9.js";const c=JSON.parse('{"title":"AI-ассистент","description":"","frontmatter":{"title":"AI-ассистент"},"headers":[],"relativePath":"ru/ai/general.md","filePath":"ru/ai/general.md"}'),e={name:"ru/ai/general.md"};function a(g,t,i,l,d,p){return n(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="ai-ассистент" tabindex="-1">AI-ассистент <a class="header-anchor" href="#ai-ассистент" aria-label="Permalink to &quot;AI-ассистент&quot;">​</a></h1><p>Вкладка <strong>AI assistant</strong> стоит после <strong>Logs</strong>. В шапке самой вкладки написано <strong>AI</strong>. Ассистент отвечает на вопросы по записанным логам и странице. Как прикрепить запрос, компонент, стор или событие лога, описано на страницах этих вкладок.</p><p>Подключение, что ассистенту можно читать, маскирование, стиль и список моделей лежат в <a href="/qa-tools/docs/ru/ai/settings.html">Options → AI</a>. Здесь описан сам чат.</p><h2 id="до-первого-вопроса" tabindex="-1">До первого вопроса <a class="header-anchor" href="#до-первого-вопроса" aria-label="Permalink to &quot;До первого вопроса&quot;">​</a></h2><p>Без ключа API вкладка пишет <strong>Connect an AI provider</strong> и предлагает <strong>Connect in Options → AI</strong>. В тексте назван бесплатный ключ Gemini или OpenRouter.</p><p>С ключом, но без подтверждения, вкладка пишет <strong>Data sent to OpenRouter</strong> или <strong>Data sent to Gemini</strong>:</p><ul><li>вопросы, выжимка записанных логов, данные событий и код страницы, который ассистент запросит;</li><li>токены, пароли, ключи API и другие значения из списка маскирования AI заменяются на <code>[MASKED]</code> до отправки; что ассистенту можно читать, задаётся в <strong>Options → AI → Agent access</strong>;</li><li>бесплатные модели могут сохранять запросы и использовать их для обучения.</li></ul><p><strong>I understand</strong> подтверждает. <strong>Review access</strong> открывает <strong>Options → AI → Agent access</strong>. До этого поле ввода недоступно и показывает <strong>Connect a provider to ask questions</strong>.</p><p>После подтверждения пустой чат предлагает четыре примера вопросов. Клик по примеру отправляет его.</p><h2 id="верхняя-панель" tabindex="-1">Верхняя панель <a class="header-anchor" href="#верхняя-панель" aria-label="Permalink to &quot;Верхняя панель&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Элемент</th><th>Поведение</th></tr></thead><tbody><tr><td>Провайдер</td><td><strong>OpenRouter</strong> или <strong>Gemini</strong></td></tr><tr><td>Модель</td><td>Видна, когда ключ задан и список моделей загружен. Первой идёт <strong>Auto</strong>: <em>free models, switches on limits</em>. Дальше группы <strong>Recommended</strong> и <strong>Added</strong>. У модели может быть пометка <strong>paid</strong>, статус, <strong>unstable</strong> и сколько запросов к ней было сегодня</td></tr><tr><td><strong>Checking models...</strong></td><td>Пока список загружается</td></tr><tr><td><strong>Models failed to load, retry</strong></td><td>Если список не загрузился. В подсказке — текст ошибки</td></tr><tr><td>Обновление</td><td>Подсказка <strong>Check which models are available</strong></td></tr><tr><td>Настройки</td><td>Подсказка <strong>AI settings: connection, access, masking, style, models</strong>. Открывает <strong>Options → AI</strong></td></tr><tr><td><strong>New chat</strong></td><td>Подсказка <strong>New chat</strong>. Недоступна, когда чат пуст и ассистент простаивает. Очищает разговор. Пока инспектор открыт, разговор сохраняется и после переключения вкладок. Перезагрузка страницы начинает пустой чат</td></tr></tbody></table><p>Список моделей скрыт, пока нет ключа и загруженных моделей.</p><h2 id="вопросы" tabindex="-1">Вопросы <a class="header-anchor" href="#вопросы" aria-label="Permalink to &quot;Вопросы&quot;">​</a></h2><p>Подсказка поля — <strong>Ask AI</strong>. С прикреплёнными плашками — <strong>Ask about the attached data</strong>.</p><p><strong>Enter</strong> отправляет. <strong>Shift+Enter</strong> переносит строку. Подсказка кнопки отправки: <strong>Send (Enter; Shift+Enter for a new line)</strong>. Для отправки нужен текст или хотя бы одна плашка. Если отправить только плашки, ассистента просят объяснить прикреплённые данные и указать, что в них не так. Плашка остаётся у вопроса; <strong>×</strong> снимает её до отправки.</p><p>Пока ответ идёт, кнопка — <strong>Stop</strong>.</p><p>Под полем, когда чат готов:</p><ul><li>OpenRouter: <strong>Today: N of M free OpenRouter requests (counted in this browser). Each assistant step is one request.</strong> <strong>M</strong> — лимит, который сообщил провайдер, или <strong>50</strong>, если он его не сообщил. В режиме <strong>Auto</strong> второй фразой идёт, сколько моделей пропущено из-за квоты или недоступности.</li><li>Gemini: <strong>Today: N Gemini requests. Daily limits depend on the model and your Google AI Studio project.</strong> Та же фраза про <strong>Auto</strong> может идти следом.</li></ul><p><strong>Auto</strong> можно выбрать, только если в списке есть модель без пометки paid. Для ручной модели она должна быть выбрана, иначе поле вопрос не примет.</p><h2 id="ответы" tabindex="-1">Ответы <a class="header-anchor" href="#ответы" aria-label="Permalink to &quot;Ответы&quot;">​</a></h2><p>Вопрос справа. Ответ слева, с именем модели и числом запросов этого ответа.</p><p><strong>Copy</strong> у сообщения копирует его текст. Подсказка становится <strong>Copied</strong>, либо появляется уведомление <strong>Could not copy to the clipboard</strong>. У блока кода в ответе своя кнопка копирования.</p><p>Ссылка <code>#N</code> в ответе открывает это событие на вкладке <strong>Logs</strong>. Если его уже нет, уведомление пишет <strong>The event is no longer in the logs</strong>.</p><p><strong>Try again</strong> у последнего ответа отправляет тот же вопрос ещё раз. Кнопка недоступна, пока идёт ответ или чат не готов.</p><p>Если выбранная модель упала по причине, которая относится именно к ней, у ответа появляется <strong>Switch to Auto and try again</strong>. Это включает <strong>Auto</strong> и отправляет вопрос снова.</p><p>Пока запуск ждёт разрешения, чат спрашивает <strong>Allow the assistant to read logs?</strong>, <strong>… page code?</strong> или <strong>… the live page?</strong>. Варианты: <strong>Allow</strong>, <strong>Allow in this chat</strong> и <strong>Deny</strong>. <strong>Allow in this chat</strong> действует до <strong>New chat</strong>.</p><p>Неудачный ответ показывает ошибку в карточке. <strong>Provider message</strong> раскрывает текст, который вернул провайдер.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ru/ai/settings.html">Options → AI</a></li><li><a href="/qa-tools/docs/ru/logs/general.html">Работа с логами</a></li><li><a href="/qa-tools/docs/ru/network/general.html">Работа с запросами</a></li><li><a href="/qa-tools/docs/ru/props/general.html">Работа с компонентами и props</a></li><li><a href="/qa-tools/docs/ru/store/general.html">Основные возможности Store</a></li></ul>',29)])])}const u=o(e,[["render",a]]);export{c as __pageData,u as default};
